package app

import "example.com/eval/billing"

// App is the composition root: every collaborator is built here and nowhere else.
type App struct {
	Invoices billing.Invoices
}

// New wires the application from its external dependencies.
func New(clock billing.Clock, store billing.Store) App {
	return App{Invoices: billing.NewInvoices(clock, store)}
}

