package billing

import (
	"fmt"
	"time"
)

// Invoice is an amount owed by a customer, due on a date.
type Invoice struct {
	ID       string
	Customer string
	Cents    int
	Due      time.Time
	Paid     bool
}

// Store persists invoices.
type Store interface {
	Save(invoice Invoice) error
	Unpaid() ([]Invoice, error)
}

// Clock tells the current time so tests can replace it.
type Clock interface {
	Now() time.Time
}

const paymentTerm = 30 * 24 * time.Hour

// Invoices issues invoices due thirty days after creation.
type Invoices struct {
	clock Clock
	store Store
}

// NewInvoices wires Invoices to its collaborators.
func NewInvoices(clock Clock, store Store) Invoices {
	return Invoices{clock: clock, store: store}
}

// Issue records a new invoice for a customer.
func (i Invoices) Issue(id, customer string, cents int) (Invoice, error) {
	invoice := Invoice{ID: id, Customer: customer, Cents: cents, Due: i.clock.Now().Add(paymentTerm)}
	if err := i.store.Save(invoice); err != nil {
		return Invoice{}, fmt.Errorf("issue invoice %s: %w", id, err)
	}
	return invoice, nil
}
